import XCTest
@testable import KipurseCore

/// On-device verification of server-built requests, including tampered ones.
final class RequestVerifyTests: XCTestCase {
  static let W = "0x1000000000000000000000000000000000000004", EX = "0x2000000000000000000000000000000000000002"
  static let V: [String: String] = [
    "good": "",
    "highSingle": "",
    "otherWallet": "",
    "otherSpender": "",
    "longTerm": "",
    "stealTransfer": "",
    "newExec": "",
  ]
  let now = Date(timeIntervalSince1970: 1_800_000_100)
  let choice = RequestVerify.Choice(single: "1000000", daily: "5000000", term: "20000000", days: 30)
  func check(_ k: String, wallet: String = W, chain: Int = 8453, exec: String? = EX) -> RequestVerify.Result {
    RequestVerify.limitsBatch(calls: [["to": wallet, "value": "0x0", "data": Self.V[k]!]], wallet: wallet, chainId: chain, choice: choice, currentExecutor: exec, now: now) }
  func testGoodLimitsBatchPasses() { let r = check("good"); XCTAssertTrue(r.ok, "\(r.problems)"); XCTAssertTrue(r.notes.isEmpty) }
  func testTamperedCapsRejected() { XCTAssertFalse(check("highSingle").ok) }
  func testOtherWalletRejected() { XCTAssertFalse(check("otherWallet").ok); XCTAssertFalse(check("good", wallet: "0x1000000000000000000000000000000000000009").ok) }
  func testOtherSpenderRejected() { XCTAssertFalse(check("otherSpender").ok) }
  func testLongerTermRejected() { XCTAssertFalse(check("longTerm").ok) }
  func testHiddenTransferRejected() { let r = check("stealTransfer"); XCTAssertFalse(r.ok); XCTAssertTrue(r.problems.contains { $0.contains("a9059cbb") || $0.contains("unknown") || $0.contains("unexpected") }) }
  func testWrongChainRejected() { XCTAssertFalse(check("good", chain: 1).ok) }
  func testExecutorChangeIsFlagged() { let r = check("newExec"); XCTAssertTrue(r.ok); XCTAssertEqual(r.notes.count, 1) }
  func testGarbageRejected() { XCTAssertFalse(RequestVerify.limitsBatch(calls: [["to": Self.W, "data": "0x1234"]], wallet: Self.W, chainId: 8453, choice: choice, currentExecutor: nil).ok)
    XCTAssertFalse(RequestVerify.limitsBatch(calls: [], wallet: Self.W, chainId: 8453, choice: choice, currentExecutor: nil).ok) }
  func approveCall(amount: UInt64, spender: String = UsdcGas.erc20Paymaster) -> [String: Any] {
    let sp = String(spender.dropFirst(spender.hasPrefix("0x") ? 2 : 0)).lowercased()
    let amt = String(amount, radix: 16)
    let data = "0x095ea7b3" + String(repeating: "0", count: 64 - sp.count) + sp + String(repeating: "0", count: 64 - amt.count) + amt
    return ["to": RequestVerify.usdc, "value": "0x0", "data": data]
  }
  func testWalletPaysRejectsAnythingButApproveThenCapChange() {
    let extra = RequestVerify.limitsBatch(calls: [["to": Self.W, "value": "0x0", "data": Self.V["good"]!], ["to": Self.W, "value": "0x0", "data": "0x"], ["to": Self.W, "data": "0x"]], wallet: Self.W, chainId: 8453, choice: choice, currentExecutor: Self.EX, now: now, walletPays: true)
    XCTAssertFalse(extra.ok); XCTAssertTrue(extra.problems.contains("wallet pays the fee itself; no refund"))
    let high = RequestVerify.limitsBatch(calls: [approveCall(amount: 50_001), ["to": Self.W, "value": "0x0", "data": Self.V["good"]!]], wallet: Self.W, chainId: 8453, choice: choice, currentExecutor: Self.EX, now: now, walletPays: true)
    XCTAssertFalse(high.ok); XCTAssertTrue(high.problems.contains("fee approve above 0.05 USDC"))
    let other = RequestVerify.limitsBatch(calls: [approveCall(amount: 8_000, spender: "0x2FAEB0760D4230Ef2aC21496Bb4F0b47D634FD4c"), ["to": Self.W, "value": "0x0", "data": Self.V["good"]!]], wallet: Self.W, chainId: 8453, choice: choice, currentExecutor: Self.EX, now: now, walletPays: true)
    XCTAssertFalse(other.ok); XCTAssertTrue(other.problems.contains("fee approve pays someone other than the USDC paymaster"))
  }
  func testWalletPaysKeepsTheCapChange() {
    let r = RequestVerify.limitsBatch(calls: [approveCall(amount: 8_000), ["to": Self.W, "value": "0x0", "data": Self.V["good"]!]], wallet: Self.W, chainId: 8453, choice: choice, currentExecutor: Self.EX, now: now, walletPays: true)
    XCTAssertTrue(r.ok, "\(r.problems)")
    XCTAssertTrue(UsdcGas.approveTargetAllowed(UsdcGas.erc20Paymaster))
  }
  func trustMsg(payees: [String] = ["0x3000000000000000000000000000000000000003"], single: String = "1000000", daily: String = "2000000", deadline: Int = 1_800_000_600, expiry: Int = 1_800_000_100 + 90 * 86400) -> OwnerTrustMessage {
    OwnerTrustMessage(account: Self.W, merchant: "0x" + String(repeating: "0", count: 64), name: "shop", epoch: "0", payees: payees, signers: [], single: single, daily: daily, expiry: String(expiry), nonce: "0x" + String(repeating: "1", count: 64), deadline: String(deadline)) }
  func testReusableTrustGood() { let e = 1_800_000_000 + 89 * 86400
    let m = trustMsg(deadline: e, expiry: e); XCTAssertTrue(RequestVerify.isReusableTrust(m))
    XCTAssertEqual(RequestVerify.trust(m, wallet: Self.W, localMaxSingle: "1000000", localMaxDaily: "2000000", now: now), []) }
  func testReusableTrustNoExpiryAccepted() { let b = trustMsg()
    let m = OwnerTrustMessage(account: b.account, merchant: b.merchant, name: b.name, epoch: b.epoch, payees: b.payees, signers: [], single: b.single, daily: b.daily, expiry: RequestVerify.noExpiry, nonce: b.nonce, deadline: RequestVerify.noExpiry)
    XCTAssertTrue(RequestVerify.isReusableTrust(m)); XCTAssertEqual(RequestVerify.trust(m, wallet: Self.W, localMaxSingle: "1000000", localMaxDaily: "2000000", now: now), []) }
  func testReusableTrustWithSignerRejected() { let e = 1_800_000_000 + 30 * 86400; let b = trustMsg(deadline: e, expiry: e)
    let m = OwnerTrustMessage(account: b.account, merchant: b.merchant, name: b.name, epoch: b.epoch, payees: b.payees, signers: ["0x4000000000000000000000000000000000000004"], single: b.single, daily: b.daily, expiry: b.expiry, nonce: b.nonce, deadline: b.deadline)
    XCTAssertTrue(RequestVerify.trust(m, wallet: Self.W, localMaxSingle: "1000000", localMaxDaily: "2000000", now: now).contains("remembered trust can only name payees")) }
  func testRememberCopyBothLanguages() {
    XCTAssertTrue(RequestVerify.rememberNote(zh: true).contains("不收任何费用")); XCTAssertTrue(RequestVerify.rememberNote(zh: true).contains("手续费"))
    XCTAssertTrue(RequestVerify.rememberNote(zh: false).contains("free")); XCTAssertTrue(RequestVerify.rememberNote(zh: false).contains("network fee"))
    XCTAssertFalse(RequestVerify.rememberNote(zh: true).contains("真钱")) }
  func testTrustGood() { XCTAssertEqual(RequestVerify.trust(trustMsg(), wallet: Self.W, localMaxSingle: "1000000", localMaxDaily: "2000000", now: now), []) }
  func testTrustTampered() {
    func bad(_ m: OwnerTrustMessage) { XCTAssertFalse(RequestVerify.trust(m, wallet: Self.W, localMaxSingle: "1000000", localMaxDaily: "2000000", now: now).isEmpty) }
    bad(trustMsg(payees: [Self.W]))                                        // pays the wallet itself
    bad(trustMsg(payees: ["0x0000000000000000000000000000000000000000"]))
    bad(trustMsg(payees: ["0x3000000000000000000000000000000000000003", "0x3000000000000000000000000000000000000003"]))
    bad(trustMsg(single: "1000001")); bad(trustMsg(daily: "9000000"))      // above this phone's own ceiling
    bad(trustMsg(deadline: 1_800_000_000)); bad(trustMsg(deadline: 1_800_100_000))
    bad(trustMsg(expiry: 1_800_000_100 + 400 * 86400))
  }
}
